import{_ as r,l as o,o as e,c as l,v as C,p as s,x as t,d as i,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"ECN","description":"","frontmatter":{"title":"ECN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ecn.md","filePath":"cs/ecn.md","lastUpdated":1789023840000}'),d={name:"cs/ecn.md"};function p(h,a,_,T,f,m){const E=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=C('<h1 id="ecn" tabindex="-1">ECN <a class="header-anchor" href="#ecn" aria-label="Permalink to &quot;ECN&quot;">​</a></h1><div class="epigraph"><p>路由器把 IP 头 CE 位置上，收端在 ACK 里回 ECE，发送方当拥塞处理而不必丢包；要两端与路径都同意。</p><footer>—— 据 RFC 3168；RFC 8311；DCTCP 课对照整理</footer></div><p><a href="/cs/aqm-red-codel">AQM</a> 可以丢也可以标。<a href="/cs/dctcp">DCTCP</a> 已用 CE。<a href="/cs/aqm-red-codel">上一课</a> 留下标记通道。缺口是 <strong>RFC 3168 协商与语义</strong>：ECT、CE、ECE、CWR。本课不把 bufferbloat 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>丢包既是信号也是损伤。ECN：拥塞时标 CE，TCP 用 ECE 通知，发端减窗并回 CWR。握手用 ECN-Echo 与 CWR 位协商能力。中间盒把 CE 清零或丢 ECT 包，则静默失败。L4S 后用不同码点，本课点名。与 PFC：ECN 端到端（路径上最挤跳），PFC 一跳。</p><p>不要把 CE 当成应用错误码。</p><p><span class="marginnote">RFC 3168。Classic ECN 一次拥塞一窗口事件；DCTCP 用比例。本课钉经典语义再对照。</span></p><h3 id="拥塞与丢包分离" tabindex="-1">拥塞与丢包分离 <a class="header-anchor" href="#拥塞与丢包分离" aria-label="Permalink to &quot;拥塞与丢包分离&quot;">​</a></h3><p>CE 沿路径最挤跳；ECE/CWR 走 TCP。中间清洗则静默失败。Classic 一次一事件，DCTCP 用比例。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：ECT 发送 → AQM 标 CE → ECE → MD → CWR。对照无 ECN：丢 → 快重传。QUIC 也有 ECN 计数，后课。</p>',11)),(e(),s(c,null,{default:t(()=>[n(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ECT%5B%22ECT%20%E5%8C%85%22%5D%20--%3E%20CE%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E6%A0%87%20CE%22%5D%0A%20%20CE%20--%3E%20ECE%5B%22ACK%20%E5%B8%A6%20ECE%22%5D%0A%20%20ECE%20--%3E%20MD%5B%22%E5%8F%91%E9%80%81%E6%96%B9%E5%87%8F%E7%AA%97%22%5D%0A%20%20MD%20--%3E%20CWR%5B%22%E9%80%9A%E7%9F%A5%E5%B7%B2%E5%93%8D%E5%BA%94%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=C('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ROCE/DCQCN 用 ECN 调速率，不是 TCP ECE。无线链路层丢包不是 CE，后课 TCP 无线会混。PMTUD 与 ECN 正交。安全：伪造 CE 可降速，需路径可信或统计。</p><p>部署：要主机栈、AQMs、不清洗的中间盒同时在。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 AccECN 的全部。缓冲膨胀是下一课。后课默认：ECN 把拥塞与丢包分离；协商失败则退回丢包信号。</p><p>只在交换机开标记、主机不开，等于没开。</p><p>上一课留下的缺口在本课收口；「ECN」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/bufferbloat">缓冲膨胀</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CE 是路径拥塞信号，ECE/CWR 走 TCP。</li><li>需端到端支持，中间不可清洗。</li><li>DCTCP 解释不同，码点可同。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3168；RFC 8311。</li></ul>',10))])}const A=r(d,[["render",p]]);export{u as __pageData,A as default};
